82	{
83	    QThreadData *data = QThreadData::current();
84	    QList<void *> &tls = data->tls;
85	    if (tls.size() <= id)
86	        tls.resize(id + 1);
87	    void **v = &tls[id];
88	
89	    DEBUG_MSG("QThreadStorageData: Returning storage %d, data %p, for thread %p",
90	          id,
91	          *v,
