class Thread : public QThread
{
    Q_OBJECT
public:
    QThreadStorage<Pointer *> &pointers;

    QMutex mutex;
    QWaitCondition cond;

    Thread(QThreadStorage<Pointer *> &p)
        : pointers(p)
    { }

    void run() override
    {
        pointers.setLocalData(new Pointer);

        QMutexLocker locker(&mutex);
        cond.wakeOne();
        cond.wait(&mutex, WaitTimeout / 2);
    }
};

void tst_QThreadStorage::autoDelete()
{
    QThreadStorage<Pointer *> pointers;
    QVERIFY(!pointers.hasLocalData());

    Thread thread(pointers);
    int c = Pointer::count;
    {
        QMutexLocker locker(&thread.mutex);
        thread.start();
        thread.cond.wait(&thread.mutex, WaitTimeout / 2);
        // QCOMPARE(Pointer::count, c + 1);
        thread.cond.wakeOne();
    }
    QVERIFY(thread.wait(WaitTimeout));
    QCOMPARE(Pointer::count, c);
}

